import ui_draw as _d
import ui_fonts as _f

WIDTH = 320
HEIGHT = 240

DEFAULTS = {
    "temperature": 21.5,  # float, -20…40
    "title": "Головна",  # str, < 24 chars
}


class UI(_d.Page):
    BACKGROUND = 0xC408  # #0b1a22
    DEFAULTS = DEFAULTS
    # (id, x, y, w, h, parameters) in layer order: the first one is the lowest.
    WIDGETS = (
        ("head", 10, 6, 302, 28, ("title",)),
        ("t_val", 10, 50, 303, 60, ("temperature",)),
        ("hint", 10, 200, 300, 24, ()),
    )

    def set_temperature(self, value):
        self.p["temperature"] = value
        return self.update()

    def set_title(self, value):
        self.p["title"] = value
        return self.update()

    def _draw_head(self, fb, ox, oy):
        # redrawn when changed: title
        p = self.p
        _d.label(
            fb,
            _d.fmt("%s", p["title"]),
            10 - ox,
            6 - oy,
            300,
            28,
            0x199F,
            _f.SERIF_16,
            _d.LEFT,
        )

    def _draw_t_val(self, fb, ox, oy):
        # redrawn when changed: temperature
        p = self.p
        _d.label(
            fb,
            _d.fmt("%.1f°C", p["temperature"]),
            10 - ox,
            50 - oy,
            300,
            60,
            0xFFFF,
            _f.SERIF_40,
            _d.LEFT,
        )

    def _draw_hint(self, fb, ox, oy):
        _d.label(fb, "Сторінка 1 з 2", 10 - ox, 200 - oy, 300, 24, 0x158D, _f.SERIF_12, _d.LEFT)
